// Des: Unit tests for pause and resume of a process tree
// Flo: parse stat lines > collect tree > real freeze and thaw of a live child
// I/O: stat text, proc lists, a spawned sleeper > pass or fail
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const ctrl = @import("ru-paus-ctrl.zig"); const regi = @import("ru-jobz-regi.zig"); const tszz = std.testing;
test "statPars reads pid, parent and group, even with spaces and brackets in the name" { const got = ctrl.statPars("123 (my) cmd (x)) S 45 67 89 0 -1").?; try tszz.expectEqual(@as(i32, 123), got.pidz); try tszz.expectEqual(@as(i32, 45), got.ppid); try tszz.expectEqual(@as(i32, 67), got.pgrp); }
test "statPars rejects junk" { try tszz.expect(ctrl.statPars("") == null); try tszz.expect(ctrl.statPars("12 no parens S 1 1") == null); try tszz.expect(ctrl.statPars(") 1 (") == null); try tszz.expect(ctrl.statPars("x (a) S 1 2") == null); try tszz.expect(ctrl.statPars("1 (a) S 2") == null); try tszz.expect(ctrl.statPars("1 (a) S z 3") == null); try tszz.expect(ctrl.statPars("1 (a) S 2 z") == null); try tszz.expect(ctrl.statPars("1 (a)") == null); }
test "treeColl takes the group, its children and grandchildren that left the group, nothing else" { const list = [_]ctrl.Proc{ .{ .pidz = 10, .ppid = 1, .pgrp = 10 }, .{ .pidz = 11, .ppid = 10, .pgrp = 10 }, .{ .pidz = 12, .ppid = 11, .pgrp = 12 }, .{ .pidz = 13, .ppid = 12, .pgrp = 13 }, .{ .pidz = 20, .ppid = 1, .pgrp = 20 }, .{ .pidz = 21, .ppid = 20, .pgrp = 20 }, .{ .pidz = 14, .ppid = 10, .pgrp = 10 } }; var mark: [7]bool = undefined; const coun = ctrl.treeColl(&list, 10, &mark); try tszz.expectEqual(@as(usize, 5), coun); try tszz.expect(mark[0] and mark[1] and mark[2] and mark[3] and mark[6]); try tszz.expect(!mark[4] and !mark[5]); }
test "treeColl finds a child whose parent is listed after it" { const list = [_]ctrl.Proc{ .{ .pidz = 30, .ppid = 29, .pgrp = 30 }, .{ .pidz = 29, .ppid = 28, .pgrp = 29 }, .{ .pidz = 28, .ppid = 1, .pgrp = 28 } }; var mark: [3]bool = undefined; const coun = ctrl.treeColl(&list, 28, &mark); try tszz.expectEqual(@as(usize, 3), coun); }
test "treeColl with no root present marks nothing" { const list = [_]ctrl.Proc{.{ .pidz = 5, .ppid = 1, .pgrp = 5 }}; var mark: [1]bool = undefined; try tszz.expectEqual(@as(usize, 0), ctrl.treeColl(&list, 99, &mark)); try tszz.expect(!mark[0]); }
test "treeFrez with no job and no leader fails, never crashes" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); try tszz.expect(!ctrl.treeFrez(iozz, null, null, true)); try tszz.expect(!ctrl.treeFrez(iozz, null, null, false)); }
fn stateChar(iozz: std.Io, pidz: i32) ?u8 { var pbuf: [40]u8 = undefined; const path = std.fmt.bufPrint(&pbuf, "/proc/{d}/stat", .{pidz}) catch return null; var file = std.Io.Dir.cwd().openFile(iozz, path, .{}) catch return null; defer file.close(iozz); var buff: [1024]u8 = undefined; const size = file.readPositionalAll(iozz, &buff, 0) catch return null; const rpar = std.mem.lastIndexOfScalar(u8, buff[0..size], ')') orelse return null; if (rpar + 2 >= size) return null; return buff[rpar + 2]; }
test "a live tree stops and continues, and an abort works while it is frozen" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); const argv: []const []const u8 = if (builtin.os.tag == .windows) &.{ "cmd", "/c", "ping -n 60 127.0.0.1 >nul" } else &.{ "sh", "-c", "setsid sleep 60 & sleep 60 & wait" }; var chil = std.process.spawn(iozz, .{ .argv = argv, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore, .pgid = if (builtin.os.tag != .windows) 0 else null, .create_no_window = true }) catch return error.SkipZigTest; const jobz = if (builtin.os.tag == .windows) (if (chil.id) |hand| regi.winzJobzCrea(hand) else null) else null; var entr = regi.Entr{ .chil = &chil, .jobz = jobz }; var live = true; defer { if (live) { regi.entrKill(&entr); _ = chil.wait(iozz) catch {}; } if (jobz) |hand| regi.jobzHandRele(hand); } if (builtin.os.tag == .windows and jobz == null) return error.SkipZigTest; std.Io.sleep(iozz, .fromMilliseconds(300), .awake) catch {}; try tszz.expect(ctrl.treeFrez(iozz, jobz, chil.id, true)); if (builtin.os.tag == .linux) { std.Io.sleep(iozz, .fromMilliseconds(150), .awake) catch {}; const pidz: i32 = @intCast(chil.id.?); try tszz.expectEqual(@as(?u8, 'T'), stateChar(iozz, pidz)); var kids: [ctrl.CF.snap]ctrl.Proc = undefined; var mark: [ctrl.CF.snap]bool = undefined; var coun: usize = 0; var dirz = try std.Io.Dir.cwd().openDir(iozz, "/proc", .{ .iterate = true }); defer dirz.close(iozz); var iter = dirz.iterate(); while (iter.next(iozz) catch null) |ent| { const pid2 = std.fmt.parseInt(i32, ent.name, 10) catch continue; var pbuf: [40]u8 = undefined; const path = std.fmt.bufPrint(&pbuf, "/proc/{d}/stat", .{pid2}) catch continue; var file = std.Io.Dir.cwd().openFile(iozz, path, .{}) catch continue; defer file.close(iozz); var buff: [1024]u8 = undefined; const size = file.readPositionalAll(iozz, &buff, 0) catch continue; if (ctrl.statPars(buff[0..size])) |item| { if (coun < kids.len) { kids[coun] = item; coun += 1; } } } const memb = ctrl.treeColl(kids[0..coun], pidz, mark[0..coun]); try tszz.expect(memb >= 3); for (kids[0..coun], 0..) |item, indx| { if (mark[indx]) try tszz.expectEqual(@as(?u8, 'T'), stateChar(iozz, item.pidz)); } } try tszz.expect(ctrl.treeFrez(iozz, jobz, chil.id, false)); if (builtin.os.tag == .linux) { std.Io.sleep(iozz, .fromMilliseconds(100), .awake) catch {}; try tszz.expect(stateChar(iozz, @intCast(chil.id.?)).? != 'T'); } try tszz.expect(ctrl.treeFrez(iozz, jobz, chil.id, true)); regi.entrKill(&entr); live = false; _ = try chil.wait(iozz); }
test "treeColl counts the leader even when it is not its own group leader" { const list = [_]ctrl.Proc{ .{ .pidz = 10, .ppid = 1, .pgrp = 5 }, .{ .pidz = 11, .ppid = 10, .pgrp = 11 }, .{ .pidz = 12, .ppid = 1, .pgrp = 12 } }; var mark: [3]bool = undefined; try tszz.expectEqual(@as(usize, 2), ctrl.treeColl(&list, 10, &mark)); try tszz.expect(mark[0] and mark[1] and !mark[2]); }
test "the registry pause clock adds up the paused time over a real freeze and thaw" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); const argv: []const []const u8 = if (builtin.os.tag == .windows) &.{ "cmd", "/c", "ping -n 30 127.0.0.1 >nul" } else &.{ "sh", "-c", "sleep 30" }; var chil = std.process.spawn(iozz, .{ .argv = argv, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore, .pgid = if (builtin.os.tag != .windows) 0 else null, .create_no_window = true }) catch return error.SkipZigTest; const jobz = if (builtin.os.tag == .windows) (if (chil.id) |hand| regi.winzJobzCrea(hand) else null) else null; var reg: regi.Regi = .{}; reg.gpaz = tszz.allocator; var entr = regi.Entr{ .chil = &chil, .jobz = jobz }; defer { regi.entrKill(&entr); _ = chil.wait(iozz) catch {}; reg.dein(tszz.allocator); } if (builtin.os.tag == .windows and jobz == null) return error.SkipZigTest; try reg.addz(iozz, "j", .{ .chil = &chil, .jobz = jobz }); try tszz.expectEqual(regi.PausCode.okzz, reg.pausSetz(iozz, "j", true, 100)); try tszz.expectEqual(@as(i64, 40), reg.pausTota(iozz, "j", 140)); try tszz.expectEqual(regi.PausCode.same, reg.pausSetz(iozz, "j", true, 200)); try tszz.expectEqual(regi.PausCode.okzz, reg.pausSetz(iozz, "j", false, 350)); try tszz.expectEqual(@as(i64, 250), reg.pausTota(iozz, "j", 999)); try tszz.expectEqual(regi.PausCode.okzz, reg.pausSetz(iozz, "j", true, 1000)); try tszz.expectEqual(regi.PausCode.okzz, reg.pausSetz(iozz, "j", false, 1100)); try tszz.expectEqual(@as(i64, 350), reg.pausTota(iozz, "j", 2000)); }
test "codeResp maps every answer to the right status and body" { const Cas = struct { code: ctrl.PausCode, onzz: bool, stat: u16, body: []const u8 }; const list = [_]Cas{ .{ .code = .okzz, .onzz = true, .stat = 200, .body = "{\"ok\":true,\"paused\":true}" }, .{ .code = .okzz, .onzz = false, .stat = 200, .body = "{\"ok\":true,\"paused\":false}" }, .{ .code = .none, .onzz = true, .stat = 409, .body = "{\"error\":\"not_running\"}" }, .{ .code = .done, .onzz = false, .stat = 409, .body = "{\"error\":\"not_running\"}" }, .{ .code = .same, .onzz = true, .stat = 409, .body = "{\"error\":\"already_paused\"}" }, .{ .code = .same, .onzz = false, .stat = 409, .body = "{\"error\":\"not_paused\"}" }, .{ .code = .fail, .onzz = true, .stat = 500, .body = "{\"error\":\"freeze_failed\"}" } }; for (list) |cas| { const got = ctrl.codeResp(cas.code, cas.onzz); try tszz.expectEqual(cas.stat, got.stat); try tszz.expectEqualStrings(cas.body, got.body); try tszz.expect(got.text.len > 0); } }
